// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 time, uint256 blockNum) public {
        vm.assume(time > 0);
        vm.assume(blockNum > 0);
        vm.warp(time);
        vm.roll(blockNum);
        vm.deal(address(this), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");
        if (success) {
            assertTrue(blockNum % 15 == 0 ? address(c).balance == 0 : address(c).balance == 10 ether);
        }
    }
}

